{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Record C35 reports absolute oral bioavailability of 93% in fasting adult TB patients, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Record C14 reports absolute oral bioavailability of 67% ± 20% in healthy fasting subjects after a 50 mg dose, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Record C05 reports an absolute oral bioavailability of 17% for nilotinib at 400 mg in patients, a below-threshold value that argues against high bioavailability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high because multiple high-transfer evidence molecules report absolute oral bioavailability well above 20% (e.g., 93%, 67%, 58%), while only one mixed molecule provides a below-threshold absolute value (17%); comparative and qualitative records do not outweigh the numeric positive evidence.",
  "evidence_gaps": [
    "Molecule 6 has conflicting absolute F records (31% in fasted humans vs 17% at 400 mg in patients) and predicted values ranging 16–25%, creating threshold uncertainty.",
    "Molecule 7 provides only comparative systemic availability versus a free acid, not an absolute F value.",
    "Molecules 9 and 10 report qualitative 'high bioavailability' without numeric F values."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

